<table border="1" cellpadding="1" cellspacing="1"><tbody><tr><td></td><td colspan="1" rowspan="1" style="text-align: center;"><strong>List-I<br>			(Oxoacids of Sulphur)</strong></td><td></td><td colspan="1" rowspan="1" style="text-align: center;"><strong>List-II<br>			(Bonds)</strong></td></tr><tr><td>A.&nbsp;</td><td>Peroxodisulphuric acid</td><td>I.</td><td>Two S-OH, Four S=O, One S-O-S</td></tr><tr><td>B.</td><td>Sulphuric acid</td><td>II.</td><td>Two S-OH, One S=O</td></tr><tr><td>C.</td><td>Pyrosulphuric acid</td><td>III.</td><td>Two S-OH, Four S=O, One S-O-O-S</td></tr><tr><td>D.&nbsp;</td><td>Sulphurous acid</td><td>IV.&nbsp;</td><td>Two S-OH, Two S=O</td></tr></tbody></table>Choose the correct answer from the options given below:&nbsp;
<table border="1" cellpadding="1" cellspacing="1"><tbody><tr><td>Options:</td><td style="text-align: center;">A</td><td style="text-align: center;">B</td><td style="text-align: center;">C</td><td style="text-align: center;">D</td></tr><tr><td>1.</td><td style="text-align: center;">III</td><td style="text-align: center;">IV</td><td style="text-align: center;">II</td><td style="text-align: center;">I</td></tr><tr><td>2.</td><td style="text-align: center;">I</td><td style="text-align: center;">III</td><td style="text-align: center;">II</td><td style="text-align: center;">IV</td></tr><tr><td>3.</td><td style="text-align: center;">III</td><td style="text-align: center;">IV</td><td style="text-align: center;">I</td><td style="text-align: center;">II</td></tr><tr><td>4.</td><td style="text-align: center;">I</td><td style="text-align: center;">III</td><td style="text-align: center;">IV</td><td style="text-align: center;">II</td></tr></tbody></table>
